data:
@FSC.hasFDerivAt_pi_of_partials : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ} {x : ι → ℝ},
  (∀ (i : ι), ∀ᶠ (y : ι → ℝ) in nhds x, HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), ContinuousAt (fun y => p y i) x) → HasFDerivAt f (FSC.piGradient (p x)) x

@FSC.contDiffAt_one_pi_of_partials : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ} {x : ι → ℝ},
  (∀ (i : ι), ∀ᶠ (y : ι → ℝ) in nhds x, HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), ∀ᶠ (y : ι → ℝ) in nhds x, ContinuousAt (fun z => p z i) y) → ContDiffAt ℝ 1 f x

@FSC.contDiffAt_two_pi_of_partials : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ} {x : ι → ℝ},
  (∀ (i : ι), ∀ᶠ (y : ι → ℝ) in nhds x, HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), ContDiffAt ℝ 1 (fun y => p y i) x) → ContDiffAt ℝ 2 f x

@FSC.hasFDerivAt_pi_of_partials_global : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ},
  (∀ (i : ι) (y : ι → ℝ), HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), Continuous fun y => p y i) → ∀ (x : ι → ℝ), HasFDerivAt f (FSC.piGradient (p x)) x

@FSC.contDiff_one_pi_of_partials : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ},
  (∀ (i : ι) (y : ι → ℝ), HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), Continuous fun y => p y i) → ContDiff ℝ 1 f

@FSC.contDiff_two_pi_of_partials : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {f : (ι → ℝ) → ℝ}
  {p : (ι → ℝ) → ι → ℝ},
  (∀ (i : ι) (y : ι → ℝ), HasDerivAt (fun a => f (Function.update y i a)) (p y i) (y i)) →
    (∀ (i : ι), ContDiff ℝ 1 fun y => p y i) → ContDiff ℝ 2 f
